-- Comments
comment on table public.delivery_proofs is 'One verified-proof record per delivered outbound shipment (N95, 20261107210300). verified needs carrier date, matching destination, an in-time scan and a $750+ signature; anything else is review. Decides not-received cases; never gates dispatch or payouts.';

-- Constraints
alter table public.delivery_proofs add constraint delivery_proofs_destination_match_check CHECK (destination_match = ANY (ARRAY['postcode'::text, 'city'::text, 'mismatch'::text, 'missing'::text]));
alter table public.delivery_proofs add constraint delivery_proofs_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(id) ON DELETE CASCADE;
alter table public.delivery_proofs add constraint delivery_proofs_pkey PRIMARY KEY (shipment_id);
alter table public.delivery_proofs add constraint delivery_proofs_shipment_id_fkey FOREIGN KEY (shipment_id) REFERENCES public.shipments(id) ON DELETE CASCADE;
alter table public.delivery_proofs add constraint delivery_proofs_verdict_check CHECK (verdict = ANY (ARRAY['verified'::text, 'review'::text]));
alter table public.delivery_proofs add constraint delivery_proofs_verified_evidence CHECK (verdict <> 'verified'::text OR cardinality(reasons) = 0 AND carrier_delivered_at IS NOT NULL AND carrier_delivered_at >= order_created_at AND first_scan_at IS NOT NULL AND first_scan_at >= order_created_at AND deliver_by IS NOT NULL AND first_scan_at <= deliver_by AND (NOT signature_required OR NULLIF(btrim(signed_by), ''::text) IS NOT NULL) AND (destination_match = 'postcode'::text AND private.postcode_key(destination_postcode, order_country) IS NOT NULL AND private.postcode_key(destination_postcode, order_country) = private.postcode_key(order_postcode, order_country) OR destination_match = 'city'::text AND private.postcode_key(destination_postcode, order_country) IS NULL AND private.city_key(destination_city) IS NOT NULL AND private.city_key(destination_city) = private.city_key(order_city)));

